export function getData (url, designWidth) {
  let pResolve, pReject
  const p = new Promise((resolve, reject) => {
    pResolve = resolve
    pReject = reject
  })

  const ws = new WebSocket(`${url}/inspector`)
  ws.onopen = function open () {
    console.log('open')
    ws.send(
      JSON.stringify({
        id: 10086,
        method: 'DOM.getDocument',
        params: {}
      })
    )
  }
  let skeleton = []
  const getRootChidren = (node, ids) => {
    // ignore node show attribute is false
    if (
      node?.attributes?.includes('show') &&
      node?.attributes?.includes('false')
    ) {
      return
    }

    // traverse this kinds of node will make layout creepy
    if (['swiper', 'text'].includes(node.nodeName)) {
      ids.add(node)
      return
    }
    // ignore loadmore node
    if (
      node.nodeName === 'list-item' &&
      node?.attributes?.includes('loadMore')
    ) {
      return
    }

    if (node.children.length === 0) {
      ids.add(node)
      return
    }

    return node.children.map((i) => getRootChidren(i, ids))
  }
  let id = 90010
  ws.onmessage = (message) => {
    const data = message.data
    console.log('onmessage', data)
    let children = new Set()
    if (typeof data === 'string') {
      console.log(data)
      const a = JSON.parse(data)
      if (a.id === 10086) {
        let root = a.result.root
        getRootChidren(root, children)
        children.forEach((i) => {
          console.log(`message id: ${id}, ${JSON.stringify(i)}`)
          ws.send(
            JSON.stringify({
              id: id++,
              method: 'CSS.getComputedStyleForNode',
              params: { nodeId: i.nodeId }
            })
          )
        })
        ws.send(
          JSON.stringify({
            id: 2048,
            method: 'Dom.Enable'
          })
        )
      } else if (a.id === 2048) {
        pResolve(skeleton)
      } else {
        if (!a.result?.computedStyle) {
          return
        }
        if (a.result.computedStyle.length === 0) {
          return
        }

        const width = a.result.computedStyle
          .find((i) => i.name === 'width')
          .value.replace('px', '')
        const height = a.result.computedStyle
          .find((i) => i.name === 'height')
          .value.replace('px', '')

        const offsetLeft = a.result.computedStyle.find(
          (i) => i.name === 'offsetLeft'
        )
        if (offsetLeft === undefined) {
          pReject(new Error('Engine not support'))
          return
        }

        const x = offsetLeft.value.replace('px', '')

        // outside of screen, ignoring.
        if (x >= designWidth) {
          return
        }

        const y = a.result.computedStyle
          .find((i) => i.name === 'offsetTop')
          .value.replace('px', '')
        if (width === 0 || height === 0) {
          return
        }

        const paddingLeft = a.result.computedStyle
          .find((i) => i.name === 'padding-left')
          .value.replace('px', '')
        const paddingRight = a.result.computedStyle
          .find((i) => i.name === 'padding-right')
          .value.replace('px', '')
        const paddingTop = a.result.computedStyle
          .find((i) => i.name === 'padding-top')
          .value.replace('px', '')
        const paddingBottom = a.result.computedStyle
          .find((i) => i.name === 'padding-bottom')
          .value.replace('px', '')

        console.log(paddingLeft, paddingRight, paddingTop, paddingBottom)
        const v = {
          x: parseInt(x) + parseInt(paddingLeft),
          y: parseInt(y) + parseInt(paddingTop),
          width:
            parseInt(width) - parseInt(paddingLeft) - parseInt(paddingRight),
          height:
            parseInt(height) - parseInt(paddingTop) - parseInt(paddingBottom)
        }
        // const v = { x, y, width, height }
        skeleton.push(v)
      }
    }
  }
  ws.onerror = (e) => {
    pReject(e)
    console.log(`error`, e)
  }
  ws.onclose = (e) => {
    console.log(`close`, e)
  }

  return p
}
