<template>
  <div id="skeleton">
    <h1>Skeleton Maker<span class="note">（需要快应用引擎>1080）</span></h1>
    <div class="input-bar">
      <input type="text" v-model="url" placeholder="请输入项目调试页面（devtool）地址，如：http://abc:8000/inspector/inspector.html?ws=def:33333/inspector..." />
      <a href="javascript:;" @click="generate"> Generate </a>
    </div>
    <div id="container">
      <textarea class="textarea item" v-model="cc"></textarea>
      <content-loader
        class="item content-loader"
        v-bind:width="clWidth"
        height="1024"
        primaryColor="#fa899d"
        secondaryColor="#ecebeb"
      >
        <rect
          v-for="(i, index) in shapes"
          :key="index"
          :x="i.x"
          :y="i.y"
          :width="i.width"
          :height="i.height"
        />
      </content-loader>
    </div>
  </div>
</template>

<script>
import { ContentLoader } from 'vue-content-loader'
import { getData } from './client'

export default {
  components: {
    ContentLoader
  },
  data () {
    return {
      url: parent.location.href,
      code: '',
      clWidth: 750,
      shapes: []
    }
  },
  computed: {
    cc: {
      get () {
        return this.code
      },
      set (newValue) {
        this.code = newValue
        this.editChange(newValue)
      }
    }
  },
  methods: {
    getUrl (debugUrl) {
      const regex = /ws=(.*)\/.*/g
      const matches = regex.exec(debugUrl)
      if (matches) {
        const url = matches[1]
        return url
      }
    },
    async generate () {
      const url = this.getUrl(this.url)
      console.log(url)
      const httpUrl = `http://${url}/runtime`
      const config = {
        method: 'get',
        url: httpUrl,
        headers: {
          message: "getManifestField('config')"
        }
      }
      const data = await this.$http(config)
      console.trace(data)
      const designWidth = data.data?.designWidth ?? 750
      this.clWidth = designWidth
      console.log(designWidth)
      const d = await getData(`ws://${url}`, designWidth)
      this.shapes = d.sort((a, b) => a.y - b.y)
      this.code = `
<skeleton width=${designWidth}>
  <clipPath id="clip-path">
    ${d.map((i) => `<rect x="${i.x}" y="${i.y}" width="${i.width}" height="${i.height}" />`)
    .join('\n')}
  </clipPath>
</skeleton>
`
    },
    editChange (str) {
      console.log('trigger')
      const regex = /\d+/gm
      const my = [...str.matchAll(regex)]
      my.shift()
      const newElements = []
      for (let i = 0; i <= my.length - 4; i = i + 4) {
        const e = {
          x: my[i][0],
          y: my[i + 1][0],
          width: my[i + 2][0],
          height: my[i + 3][0]
        }
        newElements.push(e)
      }
      this.shapes = newElements
    }
  }
}
</script>

